INSERT INTO "shp_collections" (id, name, slug, description, position, meta_title, meta_description) VALUES ('3c96714c-60a1-47f5-a160-4ef30c2c6b51', 'Oak Office Furniture', 'oak-office-furniture', 'Oak and grey oak run right through the ranges, so a desk, a pedestal, a cupboard and a meeting table can all arrive in the same finish. Warmer than white, and far more forgiving of a coffee ring.', 22, 'Oak Office Furniture | Oak Desks, Storage & Meeting Tables', 'Oak office furniture in oak and grey oak finishes: desks, pedestals, cupboards, bookcases and meeting tables that match across the whole office.');
